public class IOUtils_skip_TriageGen1Test {







    @Test
    public void testSkip_ReadFullyExhaustion() throws IOException {
        // Test the case where read < 1 (EOF) inside the readFully loop
        InputStream input = new InputStream() {
            private int pos = 0;
            private final byte[] data = "abc".getBytes();

            @Override
            public int read() {
                return (pos < data.length) ? data[pos++] & 0xFF : -1;
            }

            @Override
            public long skip(long n) throws IOException {
                return 0;
            }
        };

        // numToSkip = 10.
        // skip(10) returns 0.
        // readFully will read 3 bytes, then next call returns -1 (read < 1).
        // numToSkip will be 7.
        try {
            IOUtils.skip(input, 10);
        } catch (ArithmeticException e) {
            // Expected
        }
    }


}

